INSERT INTO testimonials (id, quote, author, product) VALUES
(1, 'I''ve tried fancy pickles from all over. Nothing comes close. The crunch is real, the heat sneaks up on you, and the jar was gone in two days.', 'Mike R.', 'Spicy Pickles'),
(2, 'Bought the Cowboy Candy at a market thinking it''d last a week. Mixed it into cream cheese that night and it was gone by Sunday. Already ordered more.', 'Sarah T.', 'Cowboy Candy'),
(3, 'I grabbed the garlic on a whim at a farmers market. Ate half the jar in the parking lot. Now I drive across town to find Jesse and stock up.', 'Carlos M.', 'Pickled Garlic'),
(4, 'You can taste the difference between this and store-bought anything. Jesse puts real love into these jars, and it shows in every bite.', 'Denver Dave', NULL),
(5, 'The Shoyu Garlic is unreal. I put it in ramen, on rice bowls, straight out of the jar — it''s umami in a way I''ve never tasted from a brined product.', 'Kim L.', 'Shoyu Garlic');
INSERT INTO class_info (id, title, price, duration, description, what_you_learn, what_you_get, max_students) VALUES
(1, 'Learn to Preserve', 125.00, '4 hours', 'Spend an afternoon with Big Sexy himself and learn how to put up jars like a pro. This isn''t a lecture — you''ll get your hands dirty. We''ll break down the science behind a perfect brine, talk spice blending, and walk through every step from raw produce to sealed jar. You''ll leave with real skills, real jars, and the confidence to start preserving on your own.',
